/* The only unknown old inputs are the pre-serialization binary80 rho,w.
 * Every operation is outward enclosed; p, powl and sqrtl results are the
 * unchanged native constants, since they never depended on rho or w. */
static std::array<I,NMOMENT> serialized(const curved::Packet&p,const GfsMaterialPoint12&v,const QuadPoint&q){
    std::array<I,NMOMENT> z;I rho=old_input(q.rho0),w=old_input(q.reference_weight),dm=rho*w,x(v.position[0]),y(v.position[1]),vx(v.velocity[0]),vy(v.velocity[1]);
    I P(p.parameters[2]*powl(v.J,-p.parameters[1])),J(v.J),div(v.grad_v[0]+v.grad_v[3]);
    z[MASS]=dm;z[PX]=dm*vx;z[PY]=dm*vy;z[ANGULAR]=dm*(x*vy-y*vx);z[KINETIC]=I(.5L)*dm*(vx*vx+vy*vy);z[THERMAL]=P*J*w/I(p.parameters[1]-1);z[VOLUME]=J*w;z[QX]=dm*x;z[QY]=dm*y;z[POLAR]=dm*(x*x+y*y);z[THERMAL_RATE]=-P*J*w*div;
    R xx=v.position[0],yy=v.position[1];z[POTENTIAL]=-dm/I(sqrtl(xx*xx+yy*yy+p.parameters[3]*p.parameters[3]));return z;
}
